configuration.config:
package Compiler is
   for Driver ("CPREP") use "${PATH(cprep)}${PREFIX(cprep)}clang";
end Compiler;

package Compiler is
   for Leading_Required_Switches ("CPREP") use
     Compiler'Leading_Required_Switches ("CPREP") & ("-E");
   for Include_Switches        ("CPREP") use ("-I");
   for Max_Command_Line_Length use "8192";
   for Response_File_Format    ("CPREP") use "GCC_GNU";
end Compiler;

package Compiler is
   for Driver ("CPREP") use "${PATH(cprep)}${PREFIX(cprep)}cpp";
end Compiler;

package Compiler is
   for Leading_Required_Switches ("CPREP") use
     Compiler'Leading_Required_Switches ("CPREP") & ("-dM");
   for Include_Switches        ("CPREP") use ("-I");
   for Max_Command_Line_Length use "8192";
   for Response_File_Format    ("CPREP") use "GCC_GNU";
end Compiler;
